ID_RE = re.compile(r"[A-Za-z0-9_.-]{1,32}\Z")
HEX_RE = re.compile(r"(?:[0-9a-f]{2})*\Z")


def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Bad()
        d[k] = v
    return d


def _const(_s):
    raise Bad()


def _isint(x):
    return type(x) is int


def _id(s):
    if type(s) is not str or not ID_RE.match(s):
        raise Bad()
    return s


def _hex(s, empty_ok=False):
    if type(s) is not str or not HEX_RE.match(s):
        raise Bad()
    if not empty_ok and not s:
        raise Bad()
    return bytes.fromhex(s)


def _keys(obj, spec):
    if type(obj) is not dict or set(obj) != spec:
        raise Bad()


