FLOW_KEYS_PLAIN = frozenset(("id", "path", "template", "kinds"))
FLOW_KEYS_REPLAY = frozenset(("id", "path", "template", "kinds", "labels"))


def parse_flow(f, mode, caps):
    if type(f) is not dict:
        raise Bad()
    _keys(f, FLOW_KEYS_REPLAY if mode == "replay" else FLOW_KEYS_PLAIN)
