def parse_request(req):
    if type(req) is not dict:
        raise Bad()
    mode = req.get("mode")
    if mode == "replay":
        _keys(req, frozenset(("mode", "capacities", "flows", "events")))
    elif mode == "plan":
        _keys(req, frozenset(("mode", "capacities", "flows", "warmup",
                              "pinned", "offers")))
    else:
        raise Bad()
    caps = req["capacities"]
    if type(caps) is not dict or not (1 <= len(caps) <= 64):
        raise Bad()
    for k, v in caps.items():
        _id(k)
        if not _isint(v) or not (0 <= v <= 512):
            raise Bad()
    flows = req["flows"]
    if type(flows) is not list:
        raise Bad()
    limit = 512 if mode == "replay" else 22
    if not (0 <= len(flows) <= limit):
        raise Bad()
    F = {}
    for f in flows:
        fid, info = parse_flow(f, mode, caps)
        if fid in F:
            raise Bad()
        F[fid] = info
    if mode == "replay":
        events = req["events"]
        if type(events) is not list or not (0 <= len(events) <= 20000):
            raise Bad()
        total_bytes = 0
        evs = []
        for ev in events:
            if type(ev) is not dict:
                raise Bad()
            op = ev.get("op")
            if op == "packet":
                _keys(ev, frozenset(("op", "flow", "header", "payload")))
                fid = _id(ev["flow"])
                if fid not in F:
                    raise Bad()
                hdr = _hex(ev["header"])
                if len(hdr) != F[fid]["H"]:
                    raise Bad()
                pay = _hex(ev["payload"], True)
                if len(pay) > 2048:
                    raise Bad()
                total_bytes += len(hdr) + len(pay)
                if total_bytes > (2 << 20):
                    raise Bad()
                evs.append(("packet", fid, hdr, pay))
            elif op == "put":
                _keys(ev, frozenset(("op", "flow", "node")))
                fid = _id(ev["flow"])
                node = _id(ev["node"])
                if fid not in F:
                    raise Bad()
                if node not in F[fid]["pidx"]:
                    raise Bad()
                evs.append(("put", fid, node))
            elif op in ("enable", "disable"):
                _keys(ev, frozenset(("op", "flow")))
                fid = _id(ev["flow"])
                if fid not in F:
                    raise Bad()
                evs.append((op, fid))
            elif op == "reset":
                _keys(ev, frozenset(("op",)))
                evs.append(("reset",))
            else:
                raise Bad()
        return {"mode": "replay", "caps": caps, "flows": F, "events": evs}
    warmup = req["warmup"]
    if not _isint(warmup) or not (0 <= warmup <= 1000000000):
        raise Bad()
    pinned = req["pinned"]
    if type(pinned) is not list:
        raise Bad()
    pin = []
    for p in pinned:
        _id(p)
        if p not in F:
            raise Bad()
        if p in pin:
            raise Bad()
        pin.append(p)
    offers = req["offers"]
    if type(offers) is not dict or set(offers) != set(F):
        raise Bad()
    hdr_bytes = 0
    runs = {}
    for fid, lst in offers.items():
        if type(lst) is not list or not (0 <= len(lst) <= 256):
            raise Bad()
        H = F[fid]["H"]
        seq = []
        tot = 0
        for r in lst:
            if type(r) is not dict:
                raise Bad()
            _keys(r, frozenset(("header", "count")))
            hdr = _hex(r["header"])
            if len(hdr) != H:
                raise Bad()
            cnt = r["count"]
            if not _isint(cnt) or not (1 <= cnt <= 1000000000):
                raise Bad()
            hdr_bytes += len(hdr)
            if hdr_bytes > 65536:
                raise Bad()
            tot += cnt
            if tot > 1000000000:
                raise Bad()
            seq.append((hdr, cnt))
        runs[fid] = seq
    return {"mode": "plan", "caps": caps, "flows": F, "warmup": warmup,
            "pinned": pin, "runs": runs}


